<?php
namespace App\Http\Controllers\Api\V1;
use App\Contracts\OtpSender;use App\Http\Controllers\Controller;use App\Models\PasswordResetSession;use App\Models\User;use App\Models\UserApprovalRequest;use App\Models\VerificationChallenge;use App\Services\ContactIdentity;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Crypt;use Illuminate\Support\Facades\Hash;use Illuminate\Support\Str;
class AuthController extends Controller
{
 public function login(Request $request, ContactIdentity $identity): JsonResponse { $data=$request->validate(['email'=>'required|email','password'=>'required|string']);$email=$identity->email($data['email']);$user=User::where('email_hash',$email['hash'])->first();abort_unless($user&&$user->password&&Hash::check($data['password'],$user->password),422,'The supplied credentials are invalid.');abort_unless(in_array($user->status,['active','pending_activation'],true),403,'This account is not active.');abort_unless($user->isSuperAdministrator(),403,'Super administrator access is required.');$user->update(['last_login_at'=>now(),'last_activity_at'=>now(),'failed_login_count'=>0]);return response()->json(['token'=>$user->createToken('admin-web')->plainTextToken,'user'=>$user]); }
 public function logout(Request $request): JsonResponse { $request->user()->currentAccessToken()?->delete();return response()->json(['message'=>'Signed out.']); }
 public function signup(Request $request,ContactIdentity $identity,OtpSender $sender):JsonResponse{$d=$request->validate(['first_name'=>'required|string|max:100','last_name'=>'nullable|string|max:100','email'=>'required|email|max:254','phone'=>['required','regex:/^\+[1-9][0-9]{7,14}$/'],'identity_region'=>'required|in:ap-south-1,eu-central-1,us-east-1','password'=>'required|string|min:12|confirmed']);$email=$identity->email($d['email']);$phone=$identity->phone($d['phone']);abort_if(User::where('email_hash',$email['hash'])->orWhere('phone_hash',$phone['hash'])->exists(),422,'Unable to register with the supplied details.');$user=User::create(['public_id'=>(string)Str::ulid(),'identity_region'=>$d['identity_region'],'first_name'=>$d['first_name'],'last_name'=>$d['last_name']??null,'display_name'=>trim($d['first_name'].' '.($d['last_name']??'')),'email_encrypted'=>$email['encrypted'],'email_hash'=>$email['hash'],'email_masked'=>$email['masked'],'phone_encrypted'=>$phone['encrypted'],'phone_hash'=>$phone['hash'],'phone_masked'=>$phone['masked'],'password'=>$d['password'],'status'=>'pending_verification','registered_via'=>'self','registration_started_at'=>now(),'verification_expires_at'=>now()->addDay()]);foreach(['email','sms']as$c){$otp=(string)random_int(100000,999999);VerificationChallenge::create(['public_id'=>(string)Str::ulid(),'user_id'=>$user->id,'channel'=>$c,'purpose'=>'signup','destination_hash'=>$c==='email'?$email['hash']:$phone['hash'],'otp_hash'=>Hash::make($otp),'status'=>'pending','expires_at'=>now()->addMinutes(5),'maximum_attempts'=>5,'last_sent_at'=>now(),'request_ip'=>$request->ip()]);$sender->send($c,$c==='email'?$d['email']:$d['phone'],$otp,'signup');}$token=Crypt::encryptString($user->public_id.'|'.now()->addMinutes(30)->timestamp);return response()->json(['data'=>['signup_token'=>$token,'status'=>$user->status]],201);}
 public function verifySignup(Request $request):JsonResponse{$d=$request->validate(['signup_token'=>'required|string','email_otp'=>'required|digits:6','mobile_otp'=>'required|digits:6']);[$publicId,$expiry]=explode('|',Crypt::decryptString($d['signup_token']),2);abort_if((int)$expiry<time(),422,'Signup verification expired.');$user=User::where('public_id',$publicId)->where('status','pending_verification')->firstOrFail();foreach(['email'=>$d['email_otp'],'sms'=>$d['mobile_otp']]as$c=>$otp){$challenge=VerificationChallenge::where(['user_id'=>$user->id,'channel'=>$c,'purpose'=>'signup','status'=>'pending'])->latest()->firstOrFail();abort_if($challenge->expires_at->isPast(),422,'OTP expired.');$challenge->increment('attempt_count');abort_if($challenge->attempt_count>$challenge->maximum_attempts,429,'Too many attempts.');abort_unless(Hash::check($otp,$challenge->otp_hash),422,'Invalid verification code.');$challenge->update(['status'=>'verified','verified_at'=>now()]);}$user->update(['email_verified_at'=>now(),'phone_verified_at'=>now(),'status'=>'pending_approval','registration_completed_at'=>now()]);UserApprovalRequest::firstOrCreate(['subject_user_id'=>$user->id,'status'=>'pending'],['public_id'=>(string)Str::ulid(),'requested_by'=>null,'required_approver_level'=>'super_admin','submitted_at'=>now()]);return response()->json(['data'=>['status'=>$user->status]]);}
 public function forgotPassword(Request $request,ContactIdentity $identity,OtpSender $sender):JsonResponse{$d=$request->validate(['email'=>'required|email','phone'=>['required','regex:/^\+[1-9][0-9]{7,14}$/']]);$email=$identity->email($d['email']);$phone=$identity->phone($d['phone']);$user=User::where('email_hash',$email['hash'])->where('phone_hash',$phone['hash'])->first();$generic=['message'=>'If the details match an account, verification codes have been sent.'];if(!$user)return response()->json($generic);$raw=Str::random(64);$session=PasswordResetSession::create(['public_id'=>(string)Str::ulid(),'user_id'=>$user->id,'session_token_hash'=>hash('sha256',$raw),'expires_at'=>now()->addMinutes(15),'request_ip'=>$request->ip()]);foreach(['email','sms']as$c){$otp=(string)random_int(100000,999999);VerificationChallenge::create(['public_id'=>(string)Str::ulid(),'user_id'=>$user->id,'channel'=>$c,'purpose'=>'password_reset','destination_hash'=>$c==='email'?$email['hash']:$phone['hash'],'otp_hash'=>Hash::make($otp),'status'=>'pending','expires_at'=>now()->addMinutes(5),'maximum_attempts'=>5,'last_sent_at'=>now(),'request_ip'=>$request->ip()]);$sender->send($c,$c==='email'?$d['email']:$d['phone'],$otp,'password_reset');}return response()->json($generic+['reset_session'=>$session->public_id.'.'.$raw]);}
 public function verifyResetOtp(Request $request):JsonResponse{$d=$request->validate(['reset_session'=>'required|string','email_otp'=>'required|digits:6','mobile_otp'=>'required|digits:6']);[$id,$raw]=explode('.',$d['reset_session'],2);$session=PasswordResetSession::where('public_id',$id)->whereNull('consumed_at')->firstOrFail();abort_if($session->expires_at->isPast()||!hash_equals($session->session_token_hash,hash('sha256',$raw)),422,'Reset session expired.');foreach(['email'=>$d['email_otp'],'sms'=>$d['mobile_otp']]as$c=>$otp){$challenge=VerificationChallenge::where(['user_id'=>$session->user_id,'channel'=>$c,'purpose'=>'password_reset','status'=>'pending'])->latest()->firstOrFail();abort_unless(Hash::check($otp,$challenge->otp_hash),422,'Invalid verification code.');$challenge->update(['status'=>'verified','verified_at'=>now()]);}$token=Str::random(64);$session->update(['email_verified_at'=>now(),'phone_verified_at'=>now(),'reset_token_hash'=>hash('sha256',$token),'reset_token_expires_at'=>now()->addMinutes(15)]);return response()->json(['reset_token'=>$session->public_id.'.'.$token]);}
 public function resetPassword(Request $request):JsonResponse{$d=$request->validate(['token'=>'required|string','password'=>'required|string|min:12|confirmed']);[$id,$raw]=explode('.',$d['token'],2);$session=PasswordResetSession::where('public_id',$id)->whereNull('consumed_at')->firstOrFail();abort_if(!$session->reset_token_expires_at||$session->reset_token_expires_at->isPast()||!hash_equals((string)$session->reset_token_hash,hash('sha256',$raw)),422,'Reset token expired.');$user=User::findOrFail($session->user_id);$user->tokens()->delete();$user->update(['password'=>$d['password'],'password_changed_at'=>now(),'credentials_version'=>$user->credentials_version+1,'failed_login_count'=>0,'locked_until'=>null]);$session->update(['consumed_at'=>now()]);return response()->json(['message'=>'Password reset successfully.']);}
 public function changePassword(Request $request):JsonResponse{$d=$request->validate(['current_password'=>'required|string','password'=>'required|string|min:12|confirmed|different:current_password']);$user=$request->user();abort_unless(Hash::check($d['current_password'],$user->password),422,'Current password is incorrect.');$user->tokens()->delete();$user->update(['password'=>$d['password'],'password_changed_at'=>now(),'must_change_password'=>false,'credentials_version'=>$user->credentials_version+1]);return response()->json(['message'=>'Password changed. Sign in again.']);}
}
